/* Local shim for owl.carousel
   Replace this file with the official minified library for fully local hosting.
   This shim loads the CDN version to provide the functionality immediately.
*/
(function(){
  if(typeof window === 'undefined') return;
  // If plugin already present, do nothing
  try{ if(window.jQuery && jQuery.fn && jQuery.fn.owlCarousel) return; }catch(e){}
  var cdn = 'https://cdn.jsdelivr.net/npm/owl.carousel@2.3.4/dist/owl.carousel.min.js';
  var s=document.createElement('script'); s.type='text/javascript'; s.async=true; s.src=cdn; document.head.appendChild(s);
})();
